package org.sleepwell.app;

import android.app.Activity;
import android.app.Dialog;
import android.content.*;
import android.os.Bundle;
import android.view.View;
import android.widget.LinearLayout;
import org.json.*;
import java.util.Locale;

/** Private, explicit saved-audio analysis. Opening never records, plays or starts inference. */
public final class RecordedRecognitionActivity extends Activity implements RecordedRecognitionJob.Observer {
    private static final int DOCUMENT=864;private RecordedRecognitionJob job;private Dialog clearDialog;private boolean credits;
    static Intent clip(Activity owner,long record,long clip,long event,long updated){return RecordUi.intent(owner,RecordedRecognitionActivity.class).putExtra("record",record).putExtra("clip",clip).putExtra("event",event).putExtra("updated",updated);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);credits=saved!=null&&saved.getBoolean("credits",false);Object retained=getLastNonConfigurationInstance();job=retained instanceof RecordedRecognitionJob?(RecordedRecognitionJob)retained:new RecordedRecognitionJob(getApplicationContext(),Records.factory,getIntent().getLongExtra("record",0),getIntent().getLongExtra("clip",0),getIntent().getLongExtra("event",0),getIntent().getLongExtra("updated",-1));if(saved!=null&&retained==null)job.message="Audio copies and unfinished analysis are not restored after process loss. Select and review the source again.";job.observe(this);}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("credits",credits);}
    @Override public Object onRetainNonConfigurationInstance(){return job;}
    @Override public void changed(){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Recorded sound estimates",this::finish);Design.space(body,12);
        Design.text(body,"Experimental · offline",14,600,Design.BROWN);Design.space(body,6);Design.text(body,"Explore laughter and instrument candidates in audio you explicitly select. Coarse windows can miss or confuse sounds; uncertain results do not prove a sound was absent.",14,400,Design.MUTED);Design.space(body,14);
        if(job.phase==RecordedRecognitionJob.Phase.READING||job.phase==RecordedRecognitionJob.Phase.ANALYZING){Design.text(body,job.progress,16,600,Design.INK);Design.space(body,10);Design.button(body,"Cancel analysis",false,job::cancel);}
        else {
            if(job.phase==RecordedRecognitionJob.Phase.READY&&job.input!=null){source(body,job.input.source,job.input.durationMs);Design.text(body,"Private memory copy · mono 16 kHz PCM16 · no resampling",12,400,Design.MUTED);Design.text(body,"Less than two seconds produces no analyzed window. No audio is saved by this tool.",12,400,Design.MUTED);Design.space(body,10);Design.button(body,"Analyze this copy",true,job::analyze);Design.button(body,"Discard copy",false,job::cancel);}
            if(job.result!=null)result(body,job.result);
            if(!job.message.isEmpty()){Design.space(body,8);Design.text(body,job.message,14,500,Design.BROWN);}
            Design.space(body,12);
            if(job.record>0&&job.clip>0)RecordUi.enabled(Design.button(body,"Prepare selected saved clip",job.input==null,job::retained),!job.busy());
            if(job.record>0&&job.clip<=0&&!job.busy()){RecordUi.heading(body,"This night’s saved recordings");Design.text(body,"Choose one retained interval. Actual WAV format and effective coverage are checked before analysis. Ending times use the current device zone.",12,400,Design.MUTED);if(job.clips.isEmpty())Design.text(body,"No saved recordings on this page.",14,400,Design.MUTED);for(RecordedRecognitionJob.ClipChoice choice:job.clips){String time=RecordUi.preciseClock(this,choice.time,java.time.ZoneId.systemDefault());android.view.View row=Design.item(body,"wave","Recording ending "+time,choice.pending?"Pending deletion":choice.duration>0?RecordUi.duration(choice.duration):"Duration checked when opened",()->job.retained(choice.id));RecordUi.enabled(row,!choice.pending);}if(job.previousClips())Design.button(body,"Previous recordings",false,()->job.pageClips(false));if(job.moreClips)Design.button(body,"More recordings",false,()->job.pageClips(true));}
            RecordUi.enabled(Design.button(body,"Choose a WAV file",job.input==null&&job.result==null,this::choose),!job.busy());
            Design.text(body,"One PCM16 mono 16 kHz WAV, up to 120 seconds and 4 MiB. Selecting a file may require its document provider; analysis itself stays on this phone.",12,400,Design.MUTED);
        }
        if(!job.busy()){RecordUi.heading(body,"Saved analyses");Design.text(body,job.saved.size()+" of 50 · summaries only, separate from sleep events",12,400,Design.MUTED);if(job.saved.isEmpty())Design.text(body,"No analyses saved yet.",14,400,Design.MUTED);for(RecordedRecognitionStore.Entry entry:job.saved){String date=RecordUi.date(entry.created,java.time.ZoneId.systemDefault());LinearLayout row=Design.row(this);LinearLayout link=Design.col(this);Design.item(link,"wave",date,entry.source.optString("kind").equals("saved_clip")?"Saved clip · "+RecordUi.duration(entry.source.optLong("durationMs")):"Selected WAV · "+RecordUi.duration(entry.source.optLong("durationMs")),()->job.open(entry));row.addView(link,new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.iconButton(this,"trash","Delete saved analysis "+date,()->job.delete(entry)),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(row);}
            if(!job.saved.isEmpty())Design.button(body,"Clear saved analyses",false,this::clear);
        }
        if(!job.busy()){Design.space(body,14);Design.button(body,credits?"Hide model license choices":"Model credits and licenses",false,()->{credits=!credits;changed();});if(credits){String[] names={"NOTICE.txt","PANN-WEIGHTS-CC-BY-4.0.txt","PANN-CODE-MIT.txt","EFFICIENTAT-MIT.txt","ONNX-RUNTIME-MIT.txt"};String[] labels={"Model credits and changes","PANN weights · CC BY 4.0","PANN code · MIT","EfficientAT · MIT","ONNX Runtime · MIT"};for(int n=0;n<names.length;n++){String file=names[n];Design.button(body,labels[n],false,()->job.notice(file));}}if(!job.notice.isEmpty()){Design.button(body,"Close model notice",false,job::hideNotice);android.widget.TextView text=Design.text(body,job.notice,12,400,Design.MUTED);text.setTextIsSelectable(true);}}
        Design.space(body,20);
    }
    private void clear(){Dialog dialog=new Dialog(this);clearDialog=dialog;dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);LinearLayout panel=Design.col(this);Design.pad(panel,22,22);panel.setBackground(Design.shape(this,Design.CREAM,22));Design.text(panel,"Clear saved analyses?",22,600,Design.INK);Design.space(panel,12);Design.text(panel,"Remove these experimental summaries. Original audio, sleep records and corrected labels stay unchanged.",14,400,Design.MUTED);Design.button(panel,"Clear summaries",true,()->{dialog.dismiss();job.clearSaved();});Design.button(panel,"Cancel",false,dialog::dismiss);dialog.setContentView(panel);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),Design.dp(this,420)),-2);}
    private void source(LinearLayout body,JSONObject value,long duration){RecordUi.heading(body,value.optString("kind").equals("saved_clip")?"Selected saved interval":"Selected WAV copy");Design.text(body,RecordUi.duration(duration),22,600,Design.INK);Design.text(body,value.optString("provenance","Source unverified"),12,400,Design.MUTED);}
    private static String clock(long ms){long seconds=ms/1000;return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    private void result(LinearLayout body,RecordedRecognitionStore.Entry entry){
        try{JSONObject data=entry.result;source(body,entry.source,entry.source.getLong("durationMs"));RecordUi.heading(body,"Experimental window estimates");Design.text(body,"Analyzed "+RecordUi.duration(data.getLong("analyzedMs"))+" · omitted "+RecordUi.duration(data.getLong("omittedMs")),13,500,Design.INK);Design.text(body,"Window positions are relative to the selected audio. Scores are uncalibrated model outputs, not confidence percentages or exact event boundaries.",12,400,Design.MUTED);JSONArray windows=data.getJSONArray("windows");
            if(windows.length()==0)Design.text(body,"No complete window of at least two seconds was available. Result is unknown.",14,500,Design.MUTED);
            for(int n=0;n<windows.length();n++){JSONObject w=windows.getJSONObject(n);String candidate=w.getString("candidate"),title=candidate.equals("laughter")?"Laughter candidate":candidate.equals("instrument")?"Instrument candidate":"Uncertain";LinearLayout card=Design.col(this);Design.pad(card,12,12);card.setBackground(Design.shape(this,Design.SOFT,14));Design.text(card,clock(w.getLong("startMs"))+"–"+clock(w.getLong("startMs")+w.getLong("durationMs"))+" · "+title,15,600,Design.INK);if(candidate.equals("instrument")&&!w.optString("instrumentLabel").isEmpty())Design.text(card,w.getString("instrumentLabel")+" · experimental class",13,400,Design.MUTED);
                JSONObject laughter=w.getJSONObject("laughter"),instrument=w.getJSONObject("instrument");Design.text(card,String.format(Locale.ROOT,"Laughter score %.3f · instrument score %.3f",laughter.getDouble("score"),instrument.getDouble("score")),12,400,Design.MUTED);body.addView(card);Design.space(body,8);}
            Design.text(body,"Model: "+data.getString("modelVersion"),11,400,Design.MUTED);Design.button(body,"Delete this analysis",false,()->job.delete(entry));
        }catch(JSONException invalid){Design.text(body,"This saved result is unreadable. Delete it and analyze the source again.",14,500,Design.BROWN);Design.button(body,"Delete unreadable analysis",false,()->job.delete(entry));}
    }
    private void choose(){if(!hasWindowFocus()||!job.choosing())return;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("audio/*"),DOCUMENT);}catch(ActivityNotFoundException|SecurityException unavailable){job.choiceCancelled("A document picker is unavailable. No audio was read.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=DOCUMENT)return;if(result!=RESULT_OK||data==null){job.choiceCancelled(null);return;}try{if(data.getClipData()!=null&&data.getClipData().getItemCount()!=1){job.choiceCancelled("Select one WAV document.");return;}job.selected(data.getData());}catch(RuntimeException invalid){job.choiceCancelled("This file selection could not be read.");}}
    @Override protected void onStop(){if(!isChangingConfigurations()&&(job.phase==RecordedRecognitionJob.Phase.ANALYZING||job.phase==RecordedRecognitionJob.Phase.READING))job.cancel();super.onStop();}
    @Override protected void onDestroy(){if(clearDialog!=null)clearDialog.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
